function widgets(){let z=$('zone');if(!z)return;z.innerHTML='';S.widgets.forEach(w=>{let e=document.createElement('div');e.className='widget';e.dataset.wid=w.id;e.style.left=w.x+'px';e.style.top=w.y+'px';e.textContent=ml(w.page);z.appendChild(e);dragWidget(e)})}
function dragWidget(e){let sx,sy,sl,st,m=false;e.addEventListener('pointerdown',q=>{m=true;sx=q.clientX;sy=q.clientY;sl=parseFloat(e.style.left);st=parseFloat(e.style.top);e.classList.add('drag');e.setPointerCapture(q.pointerId)});e.addEventListener('pointermove',q=>{if(m){e.style.left=sl+q.clientX-sx+'px';e.style.top=st+q.clientY-sy+'px'}});e.addEventListener('pointerup',q=>{if(!m)return;m=false;e.classList.remove('drag');let z=$('zone').getBoundingClientRect(),r=e.getBoundingClientRect(),i=S.widgets.findIndex(x=>x.id===e.dataset.wid);if(r.bottom<z.top+15){S.widgets.splice(i,1);save();widgets();toast(S.lang==='ru'?'Убрано с главной':'Removed from home');return}let nx=Math.max(4,Math.min(z.width-r.width-4,r.left-z.left)),ny=Math.max(4,Math.min(z.height-r.height-4,r.top-z.top));S.widgets[i].x=nx;S.widgets[i].y=ny;save();widgets();if(Math.abs(q.clientX-sx)<6&&Math.abs(q.clientY-sy)<6)go(S.widgets[i].page)})}
function menu(){let r=$('menu');if(!r)return;r.innerHTML=M.map(m=>`<div class="mitem" data-page="${m[0]}"><b>${ml(m[0])}</b><span>${S.lang==='ru'?'Нажать — открыть; потянуть — на главную':'Tap to open; drag to home'}</span><button data-open="${m[0]}">${S.lang==='ru'?'Открыть':'Open'}</button></div>`).join('');r.querySelectorAll('.mitem').forEach(dragMenu)}
function dragMenu(e){let sx,sy,m=false,g; e.addEventListener('pointerdown',q=>{if(q.target.tagName==='BUTTON')return;sx=q.clientX;sy=q.clientY;g=document.createElement('div');g.className='ghost';g.textContent=e.querySelector('b').textContent;g.style.display='none';document.body.appendChild(g);e.setPointerCapture(q.pointerId)});e.addEventListener('pointermove',q=>{if(!g)return;if(Math.abs(q.clientX-sx)>6||Math.abs(q.clientY-sy)>6){m=true;g.style.display='block';g.style.left=q.clientX-40+'px';g.style.top=q.clientY-20+'px'}});e.addEventListener('pointerup',q=>{if(g){g.remove();g=null}if(!m){go(e.dataset.page);return}m=false;if(S.page==='home'){let z=$('zone').getBoundingClientRect();if(q.clientX>=z.left&&q.clientX<=z.right&&q.clientY>=z.top&&q.clientY<=z.bottom){S.widgets.push({id:'w'+Date.now()+Math.random(),page:e.dataset.page,x:Math.max(4,Math.min(z.width-105,q.clientX-z.left-45)),y:Math.max(4,Math.min(z.height-50,q.clientY-z.top-22))});save();widgets();toast(S.lang==='ru'?'Добавлено на главную':'Added to home')}}})}
function showLeft(){$('leftMask').classList.add('on');$('leftDrawer').classList.add('open')}function hideLeft(){$('leftMask').classList.remove('on');$('leftDrawer').classList.remove('open')}function toggleLeft(){$('leftMask').classList.contains('on')?hideLeft():showLeft()}
function showRight(){menu();$('rightMask').classList.add('on');$('rightDrawer').classList.add('open')}function hideRight(){$('rightMask').classList.remove('on');$('rightDrawer').classList.remove('open')}function toggleRight(){$('rightMask').classList.contains('on')?hideRight():showRight()}
